
const pages=['产品库','榜单观察','每周精选','选用记录','AI 采集中心','规则配置'];let page=0,filter='全部平台',kind='全部信号',q='';let records=JSON.parse(localStorage.getItem('yt-records')||'[]');const games=[['叠叠小岛','微信','堆叠 / 合成','🏝️','#e1f3dc',8,32,'快速上涨','近 7 日由第 40 名升至第 8 名','将物品拖动合成，解锁岛屿空间与新资源。'],['螺丝收纳局','抖音','益智 / 螺丝','🔩','#e1e8ff',12,18,'快速上涨','连续 3 次采集排名上升','按颜色拆除螺丝，利用有限槽位完成收纳。'],['方块消消乐示例','iOS 中国','消除 / 方块','🧩','#ffe8d4',21,3,'持续表现','近 14 日有 12 日位于前 50','把不同形状的方块放入棋盘，填满整行消除。'],['Pocket Sort 示例','Google Play 美国','分类 / 收纳','🎨','#f5dff4',17,26,'本周新发现','本周首次被系统观察到；继续跟踪','将同色物品整理至相同容器，逐步解开空间限制。'],['停车解围示例','Google Play 德国','益智 / 停车','🚗','#d9f1f6',35,0,'持续表现','连续 10 日位于前 50','规划车辆离场顺序，清空拥挤停车场。'],['小猫找不同示例','Google Play 法国','找茬 / 观察','🐈','#ffe3e8',46,15,'本周新发现','首次发现入榜；尚不等同于新品','在两幅插画中找出差异，解锁新的主题场景。']].map((a,id)=>({id,name:a[0],platform:a[1],type:a[2],icon:a[3],bg:a[4],rank:a[5],up:a[6],signal:a[7],reason:a[8],desc:a[9],formal:![3,5].includes(id)}));function save(){localStorage.setItem('yt-records',JSON.stringify(records))}function nav(){document.getElementById('nav').innerHTML=pages.map((p,i)=>`<button class="${page===i?'active':''}" onclick="page=${i};render()">${['▦','↗','✦','☑','◎','⚙'][i]}　${p}</button>`).join('')}function spark(){return '<svg class="spark" viewBox="0 0 300 40" preserveAspectRatio="none"><path d="M0 36L35 31L65 33L100 23L135 27L168 16L200 20L233 9L266 13L300 3" fill="none" stroke="#35b39d" stroke-width="2"/></svg>'}function card(g){return `<div class="card"><div class="gamehead"><div class="icon" style="--bg:${g.bg}">${g.icon}</div><div><h3>${g.name}</h3><span class="muted">${g.platform} · ${g.formal?'正式库':'观察中'}</span></div></div><span class="tag">${g.type}</span><span class="tag">${g.signal}</span><div class="metrics"><div><span class="muted">热度榜排名</span><strong>#${g.rank}</strong></div><div><span class="muted">7 日排名变化</span><strong class="green">${g.up?'↑ '+g.up:'持平'}</strong></div><div><span class="muted">选用人数</span><strong>${records.filter(r=>r.id===g.id).length}</strong></div></div>${spark()}<div class="reason">${g.reason} · 示例依据</div><div class="foot"><button class="link" onclick="show(${g.id})">查看产品与历史 →</button><button class="secondary" onclick="pick(${g.id})">选用</button></div></div>`}function render(){nav();document.getElementById('crumb').textContent=pages[page];let h=`<h1>${pages[page]}</h1>`;if(page===0){h+='<div class="intro">发现经过市场验证的休闲玩法，让每一次选题都有依据。</div><div class="stats">'+[['收录产品',6],['正式入库',4],['本周新发现',2],['选用记录',records.length]].map(x=>`<div class="stat"><span class="muted">${x[0]} · 示例</span><strong>${x[1]}</strong><span class="green">持续积累市场证据</span></div>`).join('')+'</div>';h+=`<div class="toolbar"><input id="search" placeholder="搜索产品名称、玩法类型" value="${q}" oninput="q=this.value;list()"><select onchange="filter=this.value;list()">${['全部平台','微信','抖音','iOS 中国','Google Play'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><select onchange="kind=this.value;list()">${['全部信号','快速上涨','持续表现','本周新发现'].map(x=>`<option ${kind===x?'selected':''}>${x}</option>`).join('')}</select><span class="muted" style="align-self:center">默认同时展示正式库与观察候选</span></div><div id="list" class="grid"></div>`}if(page===1)h+=`<div class="notice">玩家热度与买量信号分别记录。不同平台、国家、榜单之间不直接比较名次。</div><div class="toolbar"><select id="board" onchange="board()"><option>玩家热度榜</option><option>买量榜</option></select></div><div class="panel" id="boardbody"></div>`;if(page===2)h+=`<div class="top"><p class="intro">2026.10.19 — 10.25 · 周报样式预览</p><button class="secondary" onclick="exportReport()">导出周报</button></div><div class="notice">本期演示 6 款。正式周报精选 5～10 款，不足时不凑数；观察项目明确标注，避免与正式推荐混淆。</div><div class="grid" style="margin-top:20px">${games.map(card).join('')}</div>`;if(page===3)h+=`<p class="intro">同一产品可多人选用；每条记录独立维护，无审批流程。</p><div class="panel">${recordTable(records)}</div>`;if(page===4)h+=`<div class="notice">设计方案 · 未接入 AI 模型或数据源，未启动任何定时任务。</div><h2>AI 辅助采集与识别</h2><div class="flow">${['① 获取授权数据','② AI 提取与分类','③ 校验与去重','④ 按规则入库'].map((s,i)=>`<div><b>${s}</b><p class="muted">${['API、公开网页、授权导出','名称、玩法标签、IAA 证据','来源链接、产品 ID、字段检查','正式库 / 观察中 / 待识别'][i]}</p></div>`).join('')}</div><div class="panel"><h2>数据源接入计划</h2><table><tr><th>平台</th><th>覆盖范围</th><th>采集策略</th><th>状态</th></tr>${['微信|中国','抖音|中国','iOS|中国','Google Play|美国 / 英国 / 德国 / 法国'].map(s=>`<tr><td>${s.split('|')[0]}</td><td>${s.split('|')[1]}</td><td>每日 · 优先 Top 100</td><td>待验证数据源</td></tr>`).join('')}</table></div><div class="two"><div class="panel"><h2>AI 的工作</h2><p>提取榜单字段、识别核心玩法、建议标签、整理证据、生成周报草稿。</p><p>保留原始来源、采集时间和判断依据，支持人工纠正。</p></div><div class="panel"><h2>需要准备</h2><p>数据源访问权限或授权 API；可用的 AI 模型服务；正式运行环境。</p><p>AI 无法替代付费权限；无法确认的数据标记待识别，采集失败记录异常，不补造排名。</p></div></div>`;if(page===5){const c=JSON.parse(localStorage.getItem('yt-config')||'{"top":100,"days":7,"rise":20,"weekly":8}');h+=`<div class="notice">以下是讨论用的初始阈值，需用真实样本验证后启用。保存仅影响本浏览器原型。</div><form class="panel" onsubmit="event.preventDefault();localStorage.setItem('yt-config',JSON.stringify(Object.fromEntries(new FormData(this))));document.getElementById('saved').textContent='已保存至当前浏览器'"><div class="two">${[['top','采集榜单范围（名）',c.top],['days','持续在榜观察天数',c.days],['rise','快速上涨阈值（名 / 7日）',c.rise],['weekly','每周精选数量（5～10）',c.weekly]].map(x=>`<div><label>${x[1]}</label><input name="${x[0]}" type="number" min="${x[0]==='weekly'?5:1}" ${x[0]==='weekly'?'max="10"':''} value="${x[2]}" required></div>`).join('')}</div><p>入库前提：纯 IAA 有依据；新进榜默认进入观察。</p><button class="primary">保存配置</button> <span id="saved" class="green"></span></form>`}document.getElementById('app').innerHTML=h;if(page===0)list();if(page===1)board()}
function list(){let a=games.filter(g=>(filter==='全部平台'||g.platform.includes(filter))&&(kind==='全部信号'||g.signal===kind)&&(!q||(g.name+g.type).toLowerCase().includes(q.toLowerCase())));document.getElementById('list').innerHTML=a.length?a.map(card).join(''):'<div class="empty">没有匹配的产品</div>'}function board(){let buy=document.getElementById('board').selectedIndex;document.getElementById('boardbody').innerHTML=buy?'<h2>买量榜 · 暂无数据</h2><p class="intro">接入后独立保存投放排名、素材数及原始口径，不与热度榜合并。</p>':`<h2>玩家热度榜 · 示例快照</h2><table><tr><th>平台 / 地区</th><th>产品</th><th>名次</th><th>采集日期</th><th>来源</th></tr>${games.map(g=>`<tr><td>${g.platform}</td><td><button class="link" onclick="show(${g.id})">${g.name}</button></td><td>#${g.rank}</td><td>2026-10-25</td><td>原型模拟榜单</td></tr>`).join('')}</table>`}function recordTable(rs){return rs.length?`<table><tr><th>产品 / 负责人</th><th>状态</th><th>选用 / 开始 / 完成</th><th>备注</th></tr>${rs.map(r=>`<tr><td>${games[r.id].name}<br>${esc(r.owner)}</td><td><select onchange="update('${r.key}',this.value)">${['已选','制作中','已完成','放弃'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></td><td>${r.date}<br>${r.started||'—'} / ${r.finished||'—'}</td><td>${esc(r.note)}</td></tr>`).join('')}</table>`:'<div class="empty">暂无选用记录，到产品库点击“选用”即可添加。</div>'}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function update(k,v){let r=records.find(r=>r.key===k);r.status=v;let today=new Date().toLocaleDateString('sv-SE');if(v==='制作中'&&!r.started)r.started=today;if(v==='已完成')r.finished=today;save();render()}function pick(id){const d=document.getElementById('claim');d.innerHTML=`<button class="secondary close" onclick="this.closest('dialog').close()">关闭</button><h2>选用 · ${games[id].name}</h2><p class="muted">允许多人分别选用，仅添加一条填报记录。</p><form onsubmit="add(event,${id})"><label>负责人</label><input name="owner" required maxlength="40" placeholder="填写负责人姓名"><label>备注</label><textarea name="note" rows="3" style="width:100%" maxlength="300" placeholder="可填写制作方向、项目名称等"></textarea><p><button class="primary">保存为已选</button></p></form>`;d.showModal()}function add(e,id){e.preventDefault();let f=new FormData(e.target);records.push({id,key:crypto.randomUUID(),owner:f.get('owner'),note:f.get('note'),status:'已选',date:new Date().toLocaleDateString('sv-SE')});save();document.getElementById('claim').close();render()}function show(id){let g=games[id],d=document.getElementById('detail');d.innerHTML=`<button class="secondary close" onclick="this.closest('dialog').close()">关闭</button><div class="gamehead"><div class="icon" style="--bg:${g.bg}">${g.icon}</div><div><h2>${g.name}</h2><p class="muted">${g.platform} · ${g.type}</p></div></div><div class="notice">虚构示例产品与证据，仅用于评审页面。${g.formal?'示范正式入库状态，真实版本需附 IAA 来源证据。':'新发现观察项目，尚未正式入库。'}</div><h2>核心玩法</h2><p>${g.desc}</p><div class="two"><div class="panel"><h3>截图 / 视频入口</h3><p class="muted">真实接入后展示授权截图与原始视频链接；本示例暂无素材。</p></div><div class="panel"><h3>IAA 判断依据</h3><p>证据来源：模拟数据，不构成真实判断。</p><p class="muted">真实记录包含来源链接、确认时间、广告与内购信息。</p></div></div><h2>榜单历史 · 模拟热度记录</h2><table><tr><th>日期</th><th>排名</th><th>来源</th></tr>${[0,1,2].map((n)=>`<tr><td>2026-10-${25-n*3}</td><td>#${g.rank+n*Math.round(g.up/2)}</td><td>原型模拟榜单 · ${g.platform}</td></tr>`).join('')}</table><p class="muted">首次观察：2026-10-19 ｜ 实际上线时间：未知 ｜ 数据缺失不视为掉榜</p><h2>选用记录</h2>${recordTable(records.filter(r=>r.id===id))}<p><button class="primary" onclick="pick(${id})">新增选用记录</button></p>`;d.showModal()}function exportReport(){let text='游探每周精选 · 设计原型示例\n非真实市场数据\n\n'+games.map(g=>`${g.name} | ${g.platform}\n${g.signal}：${g.reason}\n${g.desc}\n`).join('\n');let u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download='游探周报-示例.txt';a.click();URL.revokeObjectURL(u)}render();
